'use strict'

const { parentPort, workerData } = require('worker_threads')
const cds = require('@sap/cds')
const { _import, isfile, path } = cds.utils

if (workerData?.cdsRoot) cds.root = workerData.cdsRoot
if (workerData?.cdsEnv) cds.env.add(workerData.cdsEnv)

async function bootstrap() {
  const services = [
    '@sap/cds-mtxs/srv/deployment-service',
    '@sap/cds-mtxs/srv/model-provider',
    '@sap/cds-mtxs/srv/cf/saas-provisioning-service',
    '@sap/cds-mtxs/srv/extensibility-service',
  ]
  await _local_cli_js()
  cds.emit('bootstrap')
  const model = await cds.load([...services, '@sap/cds-mtxs/db/extensions'])
  cds.model = cds.compile.for.nodejs(model)
  const unserved = !cds.services['cds.xt.DeploymentService']
  if (unserved) await cds.serve(services)
  await cds.plugins
  await cds.emit('served', cds.services)
  parentPort.postMessage({ ready: true })
}

async function _local_cli_js() {
  const _local = file => isfile(file) || isfile(path.join(cds.env.folders.srv, file))
  const cli_js = process.env.CDS_TYPESCRIPT && (_local('cli.ts') || _local('server.ts')) || _local('cli.js') || _local('server.js')
  if (cli_js) await _import(cli_js)
}

parentPort.on('message', async (msg) => {
  if (msg.shutdown) {
    await cds.shutdown()
    process.exit(0)
  }
  const { id, service, op, tenant, args, cdsEnv } = msg
  if (cdsEnv) cds.env.add(cdsEnv)
  const srv = cds.services[service]
  if (!srv) {
    parentPort.postMessage({ id, error: `Service ${service} not available` })
    return
  }
  try {
    const result = await srv[op](tenant, ...Object.values(args))
    parentPort.postMessage({ id, result })
  } catch (e) {
    const error = e.message ?? 'Unknown error'
    parentPort.postMessage({ id, error })
  } finally {
    // cds.db.disconnect(cds.env.requires.multitenancy.t0 ?? 't0')
    // cds.db.disconnect(tenant)
  }
})

bootstrap().catch(e => {
  parentPort.postMessage({ error: `Bootstrap failed: ${e.message}` })
  process.exit(1)
})
